import{TIMELINE_GZIP_BASE64}from'./data/timeline-pack.js';import{PAGE_PREVIEWS_GZIP_BASE64}from'./data/pages-preview-pack.js';import{AUDIO_SAMPLES_GZIP_BASE64}from'./data/audio-samples-pack.js';import{clamp,formatTime,readConferenceLocation,conferenceUrl,sessionAt,cueAt,pageForTime,isEditingTarget}from'./engine.js';
const decode=async value=>{const bytes=Uint8Array.from(atob(value),c=>c.charCodeAt(0)),stream=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));return JSON.parse(await new Response(stream).text())};
const[timeline,previews,samples]=await Promise.all([decode(TIMELINE_GZIP_BASE64),decode(PAGE_PREVIEWS_GZIP_BASE64),decode(AUDIO_SAMPLES_GZIP_BASE64)]),$=s=>document.querySelector(s),state={...readConferenceLocation(location,timeline.event.duration),follow:true,playing:false,query:''},ui={stage:$('.slide-stage'),time:$('.time'),progress:$('[data-progress]'),deck:$('[data-deck]'),sessions:$('.sessions'),transcript:$('.transcript'),audio:$('audio'),search:$('.search'),count:$('[data-result-count]')};let sampleUrl=null,lastCue=null;
const sessionIndex=()=>Math.max(0,timeline.sessions.findIndex(x=>x===sessionAt(timeline.sessions,state.time)));function replaceUrl(){history.replaceState({conference:true},'',conferenceUrl(state))}function renderSessions(){const active=sessionAt(timeline.sessions,state.time);ui.sessions.replaceChildren(...timeline.sessions.map(item=>{const b=document.createElement('button');b.className='session'+(item===active?' active':'');b.type='button';b.textContent=`${item.id} ${item.title}`;b.onclick=()=>seek(item.start);return b}))}function renderTranscript(force=false){const q=state.query.trim().toLocaleLowerCase('ko'),cues=q?timeline.cues.filter(c=>c.text.toLocaleLowerCase('ko').includes(q)):timeline.cues,active=cueAt(timeline.cues,state.time),i=Math.max(0,timeline.cues.indexOf(active)-25),shown=q?cues.slice(0,600):timeline.cues.slice(i,i+80);ui.count.textContent=cues.length.toLocaleString('ko-KR');ui.transcript.replaceChildren(...shown.map(cue=>{const b=document.createElement('button');b.type='button';b.className='cue'+(cue===active?' active':'');const t=document.createElement('time'),s=document.createElement('span');t.textContent=formatTime(cue.start);s.textContent=cue.text;b.append(t,s);b.onclick=()=>seek(cue.start);return b}));if(force||active!==lastCue){lastCue=active;ui.transcript.querySelector('.cue.active')?.scrollIntoView({block:'nearest'})}}function renderSlide(){const page=pageForTime(timeline,state.deck,state.time);ui.stage.replaceChildren();if(page&&previews[state.deck]?.[page]){const img=document.createElement('img');img.alt=`${state.deck} ${page}쪽 저해상도 미리보기`;img.src=`data:image/webp;base64,${previews[state.deck][page]}`;ui.stage.append(img);const label=document.createElement('span');label.className='badge';label.textContent=`${page} / ${timeline.decks[state.deck].pageCount} · 검수 전 초안`;ui.stage.append(label)}else{const empty=document.createElement('div');empty.className='slide-empty';empty.textContent='이 구간은 원본 장표가 매핑되지 않았습니다.';ui.stage.append(empty)}}function render(force=false){state.time=clamp(state.time,0,timeline.event.duration);ui.progress.value=String(state.time);ui.deck.value=state.deck;ui.time.textContent=`${formatTime(state.time)} / ${formatTime(timeline.event.duration)}`;renderSlide();renderSessions();renderTranscript(force);replaceUrl()}function seek(value){state.time=clamp(value,0,timeline.event.duration);state.playing=false;ui.audio.pause();render(true)}function playSample(){const session=sessionAt(timeline.sessions,state.time);if(!session)return;if(sampleUrl)URL.revokeObjectURL(sampleUrl);const bytes=Uint8Array.from(atob(samples[session.id]),c=>c.charCodeAt(0));sampleUrl=URL.createObjectURL(new Blob([bytes],{type:'audio/ogg;codecs=opus'}));ui.audio.src=sampleUrl;ui.audio.play().then(()=>{state.playing=true;$('[data-action="play"]').textContent='❚❚'}).catch(()=>{})}
ui.audio.onended=()=>{state.playing=false;$('[data-action="play"]').textContent='▶'};ui.progress.oninput=()=>seek(ui.progress.value);ui.deck.onchange=()=>{state.deck=ui.deck.value;render(true)};ui.search.oninput=()=>{state.query=ui.search.value;renderTranscript(true)};document.onclick=e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(!action)return;const i=sessionIndex();if(action==='back')seek(state.time-10);if(action==='forward')seek(state.time+10);if(action==='prev-session')seek(timeline.sessions[Math.max(0,i-1)].start);if(action==='next-session')seek(timeline.sessions[Math.min(timeline.sessions.length-1,i+1)].start);if(action==='follow'){state.follow=!state.follow;e.target.setAttribute('aria-pressed',String(state.follow))}if(action==='play'){if(state.playing){ui.audio.pause();state.playing=false;e.target.textContent='▶'}else playSample()}};document.onkeydown=e=>{if(isEditingTarget(e.target))return;let handled=true;if(e.code==='Space'){state.playing?ui.audio.pause():playSample()}else if(e.key==='ArrowLeft')seek(state.time-(e.shiftKey?30:5));else if(e.key==='ArrowRight')seek(state.time+(e.shiftKey?30:5));else if(e.key==='[')seek(timeline.sessions[Math.max(0,sessionIndex()-1)].start);else if(e.key===']')seek(timeline.sessions[Math.min(timeline.sessions.length-1,sessionIndex()+1)].start);else if(e.key.toLowerCase()==='f'){state.follow=!state.follow;$('[data-action="follow"]').setAttribute('aria-pressed',String(state.follow))}else if(e.key.toLowerCase()==='d'){state.deck=state.deck==='r17-257'?'final-290':'r17-257';render(true)}else handled=false;if(handled)e.preventDefault()};window.onpopstate=()=>{Object.assign(state,readConferenceLocation(location,timeline.event.duration));render(true)};document.querySelectorAll('[data-tab]').forEach(button=>button.onclick=()=>{const tab=button.dataset.tab;document.querySelectorAll('[data-tab]').forEach(x=>x.setAttribute('aria-selected',String(x===button)));document.querySelector('[data-pane="slides"]').dataset.mobileHidden=String(tab!=='slides');document.querySelector('[data-pane="transcript"]').dataset.mobileHidden=String(tab!=='transcript')});render(true);
